import{_ as r,o as e,c as t,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"拔萃男书院 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-e07a8d5d","school_zh":"拔萃男书院","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"拔萃男书院 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-DBS-EARLY","C2223-DBS-MUSIC"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-e07a8d5d/s1/2022-23-interview.md","filePath":"reports/school-e07a8d5d/s1/2022-23-interview.md"}'),a={name:"reports/school-e07a8d5d/s1/2022-23-interview.md"};function n(p,o,c,d,l,i){return e(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="拔萃男书院-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">拔萃男书院 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#拔萃男书院-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;拔萃男书院 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-e07a8d5d">← 返回拔萃男书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-dbs-early" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-dbs-early" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-dbs-early}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>个人面试与提前面见</strong></p><p>常规个人面试反馈记载：先等候，再用约4分钟准备中英文文章，之后进入面试室。合集另有明确标注Early Bird的提前面见，由两位老师面见一位学生，该组称没有小组或第二次面谈。以下题目来自两类个人面试反馈，并非每位考生都会遇到。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>词语、文法及观察</strong></p><p>认读较难词语，选择其中一个造句，解释修辞并举例；用成语形容性格或态度，讲述到校上坡沿途看到的景物与感受，或看图作故事。</p><p><strong>阅读与个人学习</strong></p><p>文章主题包括祖母与相处、苦与福、自主作决定；朗读后追问内容和生活经验。词语回忆有“抱恙”“公帑”“忐忑不安”“汗流浃背”“囫囵吞枣”“兑换”“赝品”“陡峭”。</p><p><strong>家庭及文化</strong></p><p>家里是否有家务助理、上下学安排、对普教中的看法、中文成绩与改善方法、中文阅读习惯、有无兄弟姐妹及是否争吵；亦有中秋节日期、重阳与清明的区别、心目中的小人物。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>文章与自我介绍</strong></p><p>阅读或朗读后答题，材料涉及天文学或旅行家经历；部分学生觉得文章字体小、篇幅长、专有名词难读。随后自我介绍并延伸追问。</p><p><strong>择校及生活</strong></p><p>用三个形容词描述DBS、为何应录取自己、介绍英文书、周末及放学安排、对学校的认识、最近一次远足经历。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>语言体验</strong></p><p>多位考生认为中文认读、解释和即场造句较具挑战；相关难度属于个人反馈，不据此推定学校只按中文表现录取。</p></blockquote><h2 id="record-c2223-dbs-music" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-dbs-music" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-dbs-music}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>音乐试演：</strong> 中文及英语</p><p><strong>入场、演奏与问答</strong></p><p>高年级学生带领考生从等候室到两位考官所在试演室。演奏后问学习乐器多久、是否参与乐团、学校乐团是否实体排练及具体情况、在乐团的位置，以及全级名次和年级人数；中英文问题都有。</p></blockquote>',18)])])}const u=r(a,[["render",n]]);export{h as __pageData,u as default};
